1	use std::any::Any;
2	use std::sync::Arc;
3	use std::thread::JoinHandle;
4	use std::thread::{self};
5	
6	use tokio::sync::mpsc;
7	use tokio::sync::watch;
8	
9	use super::event::TokenEvent;
10	use super::event::unix_now_s;
11	use super::kv::KvCapacity;
12	use super::kv::KvPrefix;
13	use super::kv::SubmittedRequest;
14	use super::request::GenerateRequest;
15	use crate::parallel::ParallelConfig;
16	
17	/// Launch-time options for building an engine: GPU placement, parallel
18	/// topology, collective backend, graph capture toggle, seed. Consumed once by
19	/// the model crate's `start_engine` / `launch`; [`EngineHandle`] is what the
20	/// frontend holds afterwards.
21	#[derive(Clone, Debug)]
22	pub struct EngineLoadOptions {
23	    pub enable_cuda_graph: bool,
24	    pub device_ordinals: Vec<usize>,
25	    pub parallel_config: Option<ParallelConfig>,
26	    pub ep_backend: EpBackend,
27	    pub seed: u64,
28	}
29	
30	impl Default for EngineLoadOptions {
31	    fn default() -> Self {
32	        Self {
33	            enable_cuda_graph: true,
34	            device_ordinals: vec![0],
35	            parallel_config: None,
36	            ep_backend: EpBackend::Nccl,
37	            seed: 42,
38	        }
39	    }
40	}
41	
42	#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
43	pub enum EpBackend {
44	    #[default]
45	    Nccl,
46	    DeepEp,
47	}
48	
49	use super::metrics::SchedulerMetrics;
50	
51	#[derive(Clone)]
52	pub struct EngineHandle {
53	    inner: Arc<EngineInner>,
54	    servable_len: Option<u32>,
55	    /// KV pool capacity in blocks + block size, or `None` if the engine did not
56	    /// report it. See [`KvCapacity`].
57	    kv_capacity: Option<KvCapacity>,
58	    /// One optional live-load feed per scheduler partition. A normal engine
59	    /// has one partition; a data-parallel engine exposes one per logical DP
60	    /// rank. Each handle clone owns cloned receivers and `watch` fans out.
61	    metrics_watches: Vec<Option<watch::Receiver<SchedulerMetrics>>>,
62	}
63	
64	struct EngineInner {
65	    /// One submit channel per scheduler partition (logical DP rank). A
66	    /// single-partition engine holds exactly one sender.
67	    submit_txs: Vec<mpsc::UnboundedSender<SubmittedRequest>>,
68	    join_handles: Vec<JoinHandle<()>>,
69	}
70	
71	impl EngineHandle {
72	    pub fn new(submit_tx: mpsc::UnboundedSender<SubmittedRequest>) -> Self {
73	        Self::from_parts(vec![submit_tx], Vec::new())
74	    }
75	
76	    /// Construct a handle that owns the engine thread shutdown.
77	    ///
78	    /// Dropping the last handle clone closes the submit channel and then waits
79	    /// for the thread to return. That final drop may block until in-flight
80	    /// generation and backend teardown finish.
81	    pub fn new_with_join_handle(
82	        submit_tx: mpsc::UnboundedSender<SubmittedRequest>,
83	        join_handle: JoinHandle<()>,
84	    ) -> Self {
85	        Self::from_parts(vec![submit_tx], vec![join_handle])
86	    }
87	
88	    /// Construct a multi-partition handle: one submit channel and one owned
89	    /// engine thread per logical scheduler partition (e.g. one autonomous
90	    /// engine per DP rank). [`Self::submit`] routes by the request's
91	    /// `data_parallel_rank`; unbound requests go to the least-loaded
92	    /// partition (waiting requests weigh 4x, the vLLM DP policy).
93	    ///
94	    /// Dropping the last handle clone closes every channel and joins every
95	    /// thread in partition order.
96	    pub fn new_with_join_handles(
97	        submit_txs: Vec<mpsc::UnboundedSender<SubmittedRequest>>,
98	        join_handles: Vec<JoinHandle<()>>,
99	    ) -> Self {
100	        assert!(
101	            !submit_txs.is_empty(),
102	            "an engine must expose at least one scheduler partition"
103	        );
104	        Self::from_parts(submit_txs, join_handles)
105	    }
106	
107	    fn from_parts(
108	        submit_txs: Vec<mpsc::UnboundedSender<SubmittedRequest>>,
109	        join_handles: Vec<JoinHandle<()>>,
110	    ) -> Self {
111	        Self {
112	            inner: Arc::new(EngineInner {
113	                submit_txs,
114	                join_handles,
115	            }),
116	            servable_len: None,
117	            kv_capacity: None,
118	            metrics_watches: vec![None],
119	        }
120	    }
121	
122	    #[must_use]
123	    pub fn with_servable_len(mut self, servable_len: u32) -> Self {
124	        self.servable_len = Some(servable_len);
125	        self
126	    }
127	
128	    pub fn servable_len(&self) -> Option<u32> {
129	        self.servable_len
130	    }
131	
132	    #[must_use]
133	    pub fn with_kv_capacity(mut self, kv_capacity: KvCapacity) -> Self {
134	        self.kv_capacity = Some(kv_capacity);
135	        self
136	    }
137	
138	    /// KV pool capacity, if the engine reported it. A batch whose per-request
139	    /// block footprint exceeds [`KvCapacity::total_blocks`] cannot be resident
140	    /// at once.
141	    pub(crate) fn kv_capacity(&self) -> Option<KvCapacity> {
142	        self.kv_capacity
143	    }
144	
145	    #[must_use]
146	    pub fn with_metrics_watch(mut self, metrics_watch: watch::Receiver<SchedulerMetrics>) -> Self {
147	        self.metrics_watches = vec![Some(metrics_watch)];
148	        self
149	    }
150	
151	    /// Attach one load feed per logical scheduler partition.
152	    ///
153	    /// The vector is also the engine's frontend-visible DP topology, so an
154	    /// empty vector is an invalid engine rather than a single partition with
155	    /// missing metrics.
156	    #[must_use]
157	    pub fn with_metrics_watches(
158	        mut self,
159	        metrics_watches: Vec<watch::Receiver<SchedulerMetrics>>,
160	    ) -> Self {
161	        assert!(
162	            !metrics_watches.is_empty(),
163	            "an engine must expose at least one scheduler partition"
164	        );
165	        self.metrics_watches = metrics_watches.into_iter().map(Some).collect();
166	        self
167	    }
168	
169	    /// Number of logical scheduler partitions exposed to the frontend.
170	    pub(crate) fn scheduler_partition_count(&self) -> usize {
171	        self.metrics_watches.len()
172	    }
173	
174	    /// A receiver for one partition's live load, if it wired one. Awaiting
175	    /// [`watch::Receiver::changed`] wakes once per scheduler step under load and
176	    /// stays quiet when idle, so a consumer republishes on real change rather
177	    /// than polling. `None` if the partition does not report a load feed or the
178	    /// index is outside the engine topology.
179	    pub(crate) fn metrics_watch_for(
180	        &self,
181	        partition: usize,
182	    ) -> Option<watch::Receiver<SchedulerMetrics>> {
183	        self.metrics_watches.get(partition)?.clone()
184	    }
185	
186	    /// Single-partition compatibility accessor.
187	    pub fn metrics_watch(&self) -> Option<watch::Receiver<SchedulerMetrics>> {
188	        self.metrics_watch_for(0)
189	    }
190	
191	    /// Submit an unresolved request: no KV-prefix resolution ran for it, so
192	    /// the scheduler receives [`KvPrefix::none`] and prefills from its own
193	    /// GPU prefix match alone. See [`Self::submit_resolved`].
194	    #[allow(clippy::result_large_err)]
195	    pub fn submit(
196	        &self,
197	        req: GenerateRequest,
198	    ) -> std::result::Result<(), mpsc::error::SendError<GenerateRequest>> {
199	        self.submit_resolved(req, KvPrefix::none())
200	    }
201	
202	    /// Submit a request together with its KV-prefix resolution. Routing is by
203	    /// the request's `data_parallel_rank` (unbound requests go to the
204	    /// least-loaded partition), so the caller that resolved the prefix must
205	    /// have bound the request to the rank it resolved against.
206	    #[allow(clippy::result_large_err)]
207	    fn submit_resolved(
208	        &self,
209	        req: GenerateRequest,
210	        kv_prefix: KvPrefix,
211	    ) -> std::result::Result<(), mpsc::error::SendError<GenerateRequest>> {
212	        // A resolved prefix binds the request: its hold pins blocks on
213	        // the rank it resolved against, so that rank wins the routing.
214	        // A caller-bound rank that disagrees is a caller bug.
215	        let partition = match (kv_prefix.rank(), req.data_parallel_rank) {
216	            (Some(resolved), bound) => {
217	                debug_assert!(
218	                    bound.is_none_or(|b| b == resolved),
219	                    "request bound to rank {bound:?} but its prefix resolved on rank {resolved}"
220	                );
221	                resolved
222	            }
223	            (None, Some(bound)) => bound,
224	            (None, None) => self.least_loaded_partition(),
225	        };
226	        if let Some(submit_tx) = self.inner.submit_txs.get(partition) {
227	            return submit_tx
228	                .send((req, kv_prefix))
229	                .map_err(|err| mpsc::error::SendError(err.0.0));
230	        }
231	        // An out-of-range rank is a caller error, not an engine
232	        // failure: answer the request with the standard
233	        // Scheduled → Rejected pair instead of failing the submit.
234	        reject_unroutable(&req, partition, self.inner.submit_txs.len());
235	        Ok(())
236	    }
237	
238	    /// Placement for an unbound request: the partition with the lowest
239	    /// waiting-weighted load (`running + 4 × waiting`, the same weight the
240	    /// vLLM DP load balancer uses), ties to the lowest index. Scores come
241	    /// from the partitions' load watches; a partition without a feed scores
242	    /// zero, so the single-partition degenerate always returns 0.
243	    fn least_loaded_partition(&self) -> usize {
